node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Fetch promo and cart
const promo = db.prepare(\"SELECT * FROM promotions WHERE promo_code='SAVE20OFF'\").get();
const cart = db.prepare(\"SELECT * FROM carts WHERE customer_id='user_03dd1ad7'\").get();

console.log('=== VALIDATION ===');

// 1. Active?
console.log('1. Active:', promo.active === 1 ? 'PASS' : 'FAIL');

// 2. Not expired?
const today = new Date().toISOString().split('T')[0];
console.log('2. Expiry check (today=' + today + ', expires=' + promo.expiry_date + '):', today <= promo.expiry_date ? 'PASS' : 'FAIL');

// 3. Min purchase met?
console.log('3. Min purchase (cart=' + cart.subtotal + ', min=' + promo.min_purchase + '):', cart.subtotal >= promo.min_purchase ? 'PASS' : 'FAIL');

// 4. Category restriction?
const restrictions = JSON.parse(promo.category_restriction_json || '[]');
console.log('4. Category restriction:', restrictions.length === 0 ? 'PASS (no restriction)' : 'Restricted to: ' + restrictions.join(', '));

// 5. Already applied?
const appliedCodes = JSON.parse(cart.applied_promo_codes_json || '[]');
console.log('5. Not already applied:', !appliedCodes.includes('SAVE20OFF') ? 'PASS' : 'FAIL (already applied)');

// All pass - apply it
const discount = Math.min(promo.discount_value, promo.max_discount);
const newTotal = cart.subtotal - discount + cart.shipping_cost + cart.gift_wrap_fee - cart.loyalty_discount;
const newApplied = JSON.stringify([...appliedCodes, 'SAVE20OFF']);

console.log('\n=== APPLYING ===');
console.log('Discount amount: \$' + discount);
console.log('New total: \$' + newTotal);

db.prepare('UPDATE carts SET discount_amount = ?, total = ?, applied_promo_codes_json = ? WHERE cart_id = ?')
  .run(discount, newTotal, newApplied, cart.cart_id);

// Verify
const updated = db.prepare(\"SELECT * FROM carts WHERE customer_id='user_03dd1ad7'\").get();
console.log('\n=== UPDATED CART ===');
console.log(JSON.stringify(updated, null, 2));
"
